<?php
namespace App\Console\Commands;
use App\Services\GuiasInternasGatewayClient; use App\Services\GuiasInternasHistoricoService; use Illuminate\Console\Command; use Illuminate\Support\Facades\Cache;
class SincronizarGuiasInternas extends Command { protected $signature='guias-internas:sincronizar {--desde=2025-12-01} {--hasta=} {--locales=*} {--iniciado-por=} {--sync-id=}'; protected $description='Sincroniza y reconcilia las Guías internas de Restaurant en la copia local.'; public function handle(GuiasInternasHistoricoService $service,GuiasInternasGatewayClient $gateway):int{$lock=Cache::lock('guias-internas:sync',14400);if(!$lock->get()){$this->info('Ya hay una sincronización de Guías internas en curso.');return self::SUCCESS;}try{$locales=array_values(array_filter((array)$this->option('locales')));$sync=filled($this->option('sync-id'))?\App\Models\GuiaInternaSincronizacion::query()->findOrFail((int)$this->option('sync-id')):$service->iniciar((string)$this->option('desde'),(string)($this->option('hasta')?:now()->toDateString()),$locales,filled($this->option('iniciado-por'))?(int)$this->option('iniciado-por'):null);if($locales===[])$locales=array_values(array_filter((array)($sync->filtros['locales']??[])));$this->info(json_encode($service->sincronizar($sync,$gateway,$locales)));return self::SUCCESS;}catch(\Throwable $e){if(isset($sync))$sync->update(['estado'=>'fallido','mensaje_error'=>$e->getMessage(),'completado_en'=>now()]);throw $e;}finally{$lock->release();}} }
